# WAR ARENA - Final Review Fixes (capability truth-up) - Installer
# Updates capabilities.ts to reflect what was actually built (gmgn_live/auth/http
# = VERIFIED, etc) and the tests that guard those states. Run from project root:
#   powershell -ExecutionPolicy Bypass -File .\install-review-fixes.ps1
$ErrorActionPreference = "Stop"
Write-Host "WAR - Final review fixes installer" -ForegroundColor Cyan
function Write-B64([string]$Path,[string]$B64){
  $dir = Split-Path -Parent $Path
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Force -Path $dir | Out-Null }
  [System.IO.File]::WriteAllBytes($Path,[System.Convert]::FromBase64String($B64))
  Write-Host "  wrote $Path" -ForegroundColor DarkGray
}

Write-B64 "src/arena/capabilities.ts" ""
Write-B64 "tests/integration/arena.test.ts" ""

Write-Host ""; Write-Host "Verifying gate ..." -ForegroundColor Cyan
npx tsc --noEmit; if ($LASTEXITCODE -ne 0){ throw "typecheck failed" }
npx vitest run
Write-Host ""; Write-Host "Review fixes installed. Expected: 974 passed + 1 skipped, 454 guards." -ForegroundColor Green
